import React, { useState, useEffect } from "react";
import api from "../api";

export default function AdminDashboard() {
  const [activeTab, setActiveTab] = useState("VotingStatus");
  const [sidebarOpen, setSidebarOpen] = useState(true);
  const [message, setMessage] = useState("");
  const [summary, setSummary] = useState({
    totalStudents: 0,
    totalVoted: 0,
    voters: [],
  });

  // Handle API errors
  const handleApiError = (err) => {
    console.error("API Error:", err);
    if (err.response) {
      setMessage(err.response.data.error || "Server Error");
    } else {
      setMessage("Network Error");
    }
  };

  // Fetch voting summary
  const fetchVotingSummary = async () => {
    try {
      const res = await api.get("/admin/voting-summary");
      setSummary(res.data);
    } catch (err) {
      handleApiError(err);
    }
  };

  // Initialize
  useEffect(() => {
    fetchVotingSummary();
  }, []);

  // Logout
  const logout = () => {
    localStorage.removeItem("token");
    window.location.href = "/login";
  };

  // Render content based on tab
  const renderContent = () => {
    switch (activeTab) {
      case "VotingSummary":
        return (
          <div>
            <h2 style={{ marginBottom: "15px" }}>Voting Summary</h2>
            <p style={{ fontWeight: "bold" }}>
              Total Voted: {summary.totalVoted} / {summary.totalStudents}
            </p>
            <table
              style={{
                width: "100%",
                borderCollapse: "collapse",
                marginTop: "15px",
              }}
            >
              <thead>
                <tr style={{ background: "#f1f1f1" }}>
                  <th style={{ padding: "8px", textAlign: "left" }}>
                    Student #
                  </th>
                  <th style={{ padding: "8px", textAlign: "left" }}>Name</th>
                  <th style={{ padding: "8px", textAlign: "center" }}>
                    Status
                  </th>
                </tr>
              </thead>
              <tbody>
                {summary.voters?.map((v) => (
                  <tr key={v.id} style={{ borderTop: "1px solid #eee" }}>
                    <td style={{ padding: "8px" }}>{v.studentNumber}</td>
                    <td style={{ padding: "8px" }}>{v.name}</td>
                    <td
                      style={{
                        padding: "8px",
                        textAlign: "center",
                        color: v.status === "Voted" ? "green" : "red",
                        fontWeight: "bold",
                      }}
                    >
                      {v.status}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        );

      case "VotingStatus":
        return <div><h2>Voting Status</h2><p>Coming soon…</p></div>;
      case "PendingUsers":
        return <div><h2>Pending Users</h2><p>Coming soon…</p></div>;
      case "Candidates":
        return <div><h2>Candidates</h2><p>Coming soon…</p></div>;
      case "Results":
        return <div><h2>Results</h2><p>Coming soon…</p></div>;
      case "Reports":
        return <div><h2>Reports</h2><p>Coming soon…</p></div>;
      default:
        return <p>Select a tab</p>;
    }
  };

  return (
    <div style={{ display: "flex", height: "100vh", background: "#f9f9f9" }}>
      {/* Sidebar */}
      <aside
        style={{
          width: sidebarOpen ? "250px" : "60px",
          background: "#343a40",
          color: "#fff",
          transition: "width 0.3s",
          display: "flex",
          flexDirection: "column",
          position: "relative",
        }}
      >
        <button
          onClick={() => setSidebarOpen(!sidebarOpen)}
          style={{
            background: "none",
            border: "none",
            color: "#fff",
            fontSize: "1.2rem",
            cursor: "pointer",
            position: "absolute",
            top: "10px",
            right: sidebarOpen ? "10px" : "-30px",
          }}
        >
          {sidebarOpen ? "←" : "→"}
        </button>
        <nav style={{ marginTop: "40px" }}>
          {[
            { key: "VotingSummary", label: "Voting Summary" },
            { key: "VotingStatus", label: "Voting Status" },
            { key: "PendingUsers", label: "Pending Users" },
            { key: "Candidates", label: "Candidates" },
            { key: "Results", label: "Results" },
            { key: "Reports", label: "Reports" },
          ].map((item) => (
            <div
              key={item.key}
              onClick={() => setActiveTab(item.key)}
              style={{
                padding: "12px 20px",
                cursor: "pointer",
                background:
                  activeTab === item.key ? "#007bff" : "transparent",
                fontWeight: activeTab === item.key ? "bold" : "normal",
              }}
            >
              {sidebarOpen ? item.label : item.label[0]}
            </div>
          ))}
        </nav>
        <button
          onClick={logout}
          style={{
            marginTop: "auto",
            marginBottom: "20px",
            padding: "10px 20px",
            borderRadius: "8px",
            border: "none",
            backgroundColor: "#dc3545",
            color: "#fff",
            cursor: "pointer",
            fontWeight: "bold",
            width: "90%",
            alignSelf: "center",
          }}
        >
          Logout
        </button>
      </aside>

      {/* Main Content */}
      <main style={{ flex: 1, padding: "30px" }}>
        <h1 style={{ marginBottom: "20px", color: "#333" }}>
          Admin Dashboard
        </h1>
        {message && (
          <p style={{ color: "red", marginBottom: "20px" }}>{message}</p>
        )}
        {renderContent()}
      </main>
    </div>
  );
}
